gallery=''.join([IMG(s,a) for s,a in [('coorg-homestay-hero.webp','ಹೋಂಸ್ಟೇ ಹೊರಾಂಗಣ'),('coorg-homestay-entrance-greenery.webp','ಹೋಂಸ್ಟೇ ಪ್ರವೇಶ ಮತ್ತು ಹಸಿರು'),('coorg-homestay-property.webp','ಹೋಂಸ್ಟೇ ಮುಂಭಾಗ'),('coorg-homestay-bedroom-blue.webp','ನೀಲಿ ಅಲಂಕಾರದ ಮಲಗುವ ಕೋಣೆ'),('coorg-homestay-bedroom-purple.webp','ಮಲಗುವ ಕೋಣೆ'),('coorg-homestay-bedroom-3.webp','ಮೂರನೇ ಮಲಗುವ ಕೋಣೆ'),('coorg-homestay-bedroom-red.webp','ಮಲಗುವ ಕೋಣೆ ಮತ್ತು ಕೊಡಗಿನ ಚಿತ್ರಗಳು'),('coorg-homestay-living-room.webp','ಸಾಮಾನ್ಯ ವಾಸದ ಸ್ಥಳ'),('coorg-homestay-common-area.webp','ಸಾಮಾನ್ಯ ಪ್ರದೇಶ'),('coorg-homestay-washroom.webp','ಸ್ನಾನಗೃಹ')]])
attrs=[('coffee-plantations.svg','ಕೊಡಗಿನ ಕಾಫಿ ತೋಟ','ಕಾಫಿ ಮತ್ತು ಪ್ರಕೃತಿ','Greenway Coffee Island Plantation Tour','ಕಾಫಿ ತೋಟದ ವಾತಾವರಣ ಮತ್ತು ಪ್ರಕೃತಿಯನ್ನು ಹತ್ತಿರದಿಂದ ಅನುಭವಿಸಲು ಸಮೀಪದ ಆಯ್ಕೆ.','11'),('nisargadhama.svg','ಕಾವೇರಿ ನಿಸರ್ಗಧಾಮ','ಪ್ರಕೃತಿ','Kaveri Nisargadhama','ಕಾವೇರಿ ನದಿಯ ಮೇಲಿನ ಹಸಿರು ದ್ವೀಪ; ನಿಧಾನವಾದ ಪ್ರಕೃತಿ ವಿಹಾರಕ್ಕೆ ಸೂಕ್ತ.','22'),('chiklihole-reservoir.svg','ಚಿಕ್ಲಿಹೊಳೆ ಜಲಾಶಯ','ದೃಶ್ಯ ತಾಣ','Chiklihole Reservoir','ಹಸಿರಿನಿಂದ ಸುತ್ತುವರಿದ ಶಾಂತ ಜಲಾಶಯ; ದೃಶ್ಯ ಮತ್ತು ಛಾಯಾಗ್ರಹಣಕ್ಕೆ ಸೂಕ್ತ.','24'),('rajas-seat.svg','ರಾಜಾಸೀಟ್','ವೀಕ್ಷಣಾ ತಾಣ','Raja’s Seat','ಮಡಿಕೇರಿಯ ಪ್ರಸಿದ್ಧ ನೋಟದ ತಾಣ; ಬೆಟ್ಟ ಮತ್ತು ಕಣಿವೆಗಳ ವಿಶಾಲ ದೃಶ್ಯ.','25'),('madikeri-fort.svg','ಮಡಿಕೇರಿ ಕೋಟೆ','ಪರಂಪರೆ','Madikeri Fort','ಮಡಿಕೇರಿಯ ಇತಿಹಾಸದ ಪ್ರಮುಖ ಗುರುತು ಮತ್ತು ನಗರ ಪ್ರವಾಸದ ಭಾಗ.','25'),('harangi-reservoir.svg','ಹಾರಂಗಿ ಜಲಾಶಯ','ನೀರು ಮತ್ತು ಪ್ರಕೃತಿ','Harangi Reservoir / Backwaters','ನೀರು, ಹಸಿರು ಮತ್ತು ಶಾಂತ ದೃಶ್ಯಗಳಿಗಾಗಿ ಒಂದು ದಿನದ ಪ್ರವಾಸದ ಆಯ್ಕೆ.','31–32'),('abbey-falls.svg','ಅಬ್ಬೆ ಜಲಪಾತ','ಜಲಪಾತ','Abbey Falls','ಕಾಫಿ ಮತ್ತು ಮಸಾಲೆ ತೋಟಗಳ ನಡುವೆ ಇರುವ ಜನಪ್ರಿಯ ಜಲಪಾತ.','33'),('dubare-elephant-camp.svg','ದುಬಾರೆ ಆನೆ ಶಿಬಿರ','ಸಾಹಸ','Dubare Elephant Camp','ಕಾವೇರಿ ತೀರದ ಪ್ರಕೃತಿ ಮತ್ತು ಆನೆಗಳ ಅನುಭವಕ್ಕೆ ಪ್ರಸಿದ್ಧ ತಾಣ.','35'),('golden-temple.svg','ನಮ್ದ್ರೋಲಿಂಗ್ ಮಠ / ಗೋಲ್ಡನ್ ಟೆಂಪಲ್','ಸಂಸ್ಕೃತಿ','Namdroling Monastery / Golden Temple','ಬೈಲಕುಪ್ಪೆಯ ಪ್ರಸಿದ್ಧ ಟಿಬೆಟಿಯನ್ ಬೌದ್ಧ ಮಠ ಮತ್ತು ಚಿನ್ನದ ಪ್ರತಿಮೆಗಳ ತಾಣ.','36'),('mandalpatti.svg','ಮಂಡಲ್ಪಟ್ಟಿ ಶಿಖರ','ಬೆಟ್ಟಗಳು','Mandalpatti Peak','ಮಂಜು, ಬೆಟ್ಟಗಳ ವಿಶಾಲ ನೋಟ ಮತ್ತು 4x4 ಮಾರ್ಗಗಳಿಗೆ ಜನಪ್ರಿಯ ಎತ್ತರದ ತಾಣ.','1 ಗಂ. 21 ನಿ.')]
attractions=''.join([f'<article class="card"><div class="img-ph ratio-16-9"><img src="../images/places/{p}" alt="{alt}" loading="lazy" decoding="async"></div><div class="card-body"><span class="tag">{tag}</span><h2 style="font-size:1.35rem;margin-top:.65rem;">{name}</h2><p>{d}</p><p style="font-size:.85rem;color:var(--ink-700);font-weight:600;">ಅಂದಾಜು {mins} ನಿಮಿಷಗಳ ಪ್ರಯಾಣ</p><a href="https://www.google.com/maps/search/?api=1&query={name.replace(" ","%20")}%2C%20Coorg%2C%20Karnataka" class="btn btn-ghost btn-sm" target="_blank" rel="noopener">ಗೂಗಲ್ ಮ್ಯಾಪ್ಸ್‌ನಲ್ಲಿ ನೋಡಿ</a></div></article>' for p,alt,tag,name,d,mins in attrs])

for filename,(title,desc,body) in pages.items():
    body=body.replace('{ROOMCARDS}',roomcards).replace('{GALLERY}',gallery).replace('{ATTRACTIONS}',attractions)
    kn.joinpath(filename).write_text(shell(title,desc,filename,body),encoding='utf-8')

# language-specific styling: load web-safe Unicode Kannada fonts from Google as fallback; Sanchaya-listed Nudi/Inchara remain fallback names.
(root/'css'/'kannada.css').write_text('''/* Kannada typography layer. Sanchaya is the Kannada font catalogue; this stack uses Unicode-safe Kannada rendering with Sanchaya-listed font names as local fallbacks. */\n@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+Kannada:wght@400;500;600;700&family=Noto+Serif+Kannada:wght@500;600;700&display=swap");\n''',encoding='utf-8')
# Add CSS import to kn pages after style.css
for f in kn.glob('*.html'):
    s=f.read_text(encoding='utf-8').replace('<link rel="stylesheet" href="../css/style.css">','<link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/kannada.css">')
    f.write_text(s,encoding='utf-8')
print('created',len(list(kn.glob('*.html'))),'Kannada pages')
